import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { describe, expect, it } from "vitest";
import { MEMORY_HEALTH_ISSUE_CODES, type MemoryHealthIssueCode } from "../health-metadata.js";

// Frozen from the pre-extraction ordered wire vocabulary, not generated by the implementation.
const ORDERED_CODES_SHA256 = "b4ffd57ce6563a669ffe403309ef1a05d244fa8caeaf6dc2b1d533745bb35940";

describe("code-only memory health metadata", () => {
  it("preserves the exact ordered issue vocabulary", () => {
    const code: MemoryHealthIssueCode = "manifest_missing";
    expect(MEMORY_HEALTH_ISSUE_CODES[0]).toBe(code);
    expect(MEMORY_HEALTH_ISSUE_CODES).toHaveLength(25);
    expect(new Set(MEMORY_HEALTH_ISSUE_CODES).size).toBe(25);
    expect(createHash("sha256").update(JSON.stringify(MEMORY_HEALTH_ISSUE_CODES)).digest("hex"))
      .toBe(ORDERED_CODES_SHA256);
  });

  it("loads the built entry while refusing every transitive module load", () => {
    const target = new URL("../../dist/health-metadata.js", import.meta.url).href;
    const output = execFileSync(process.execPath, ["--input-type=module", "--eval", `
      import { registerHooks } from "node:module";
      const target = ${JSON.stringify(target)};
      registerHooks({ load(url, context, next) {
        if (url !== target) throw new Error("Metadata imported another module: " + url);
        return next(url, context);
      } });
      const { MEMORY_HEALTH_ISSUE_CODES } = await import(target);
      console.log(MEMORY_HEALTH_ISSUE_CODES.length);
    `], { encoding: "utf8" });
    expect(output.trim()).toBe("25");
  });
});
